// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import {
    createCollection,
    createLink,
    createHighlight,
    getHighlights,
    updateHighlight,
    deleteHighlight,
    deleteCollection,
} from './skyrampUtils';

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const collectionsPostRequestBody: string = `{
        "color": "#0ea5e9",
        "description": "",
        "name": "Highlights Lifecycle"
    }`;

    const collectionsPostResponse = await createCollection(client, headers, collectionsPostRequestBody);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionsPostResponse, "response.name"), 'name').toBe("Highlights Lifecycle");
    expect(getResponseValue(collectionsPostResponse, "response.color"), 'color').toBe("#0ea5e9");
    expect(getResponseValue(collectionsPostResponse, "response.description"), 'description').toBe("");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(collectionsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "id": 9001
        },
        "description": "",
        "name": "Lifecycle Source",
        "tags": [],
        "type": "url",
        "url": "https://example.com/lifecycle"
    }`;

    const linksPostResponse = await createLink(
        client,
        headers,
        linksPostRequestBody,
        {"collection.id": getResponseValue(collectionsPostResponse, "response.id")}
    );
    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Lifecycle Source");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/lifecycle");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'collectionId').toBe(getResponseValue(collectionsPostResponse, "response.id"));
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);

    // Request Body
    const highlightsPostRequestBody: string = `{
        "color": "green",
        "comment": "lifecycle annotation",
        "endOffset": 17,
        "linkId": 9002,
        "startOffset": 0,
        "text": "Lifecycle passage"
    }`;

    const highlightsPostResponse = await createHighlight(
        client,
        headers,
        highlightsPostRequestBody,
        {"linkId": getResponseValue(linksPostResponse, "response.id")}
    );
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(highlightsPostResponse, "response.color"), 'color').toBe("green");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'comment').toBe("lifecycle annotation");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'text').toBe("Lifecycle passage");
    expect(getResponseValue(highlightsPostResponse, "response.startOffset"), 'startOffset').toBe(0);
    expect(getResponseValue(highlightsPostResponse, "response.endOffset"), 'endOffset').toBe(17);
    expect(getResponseValue(highlightsPostResponse, "response.linkId"), 'linkId').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(highlightsPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const highlightsGetResponse = await getHighlights(client, headers, {"color": ["green"]});
    expect(highlightsGetResponse.statusCode, 'status code').toBe(200);

    // Ordered id-descending, so the highlight this test just created is index 0.
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.id"), 'listed id').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.color"), 'listed color').toBe("green");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.comment"), 'listed comment').toBe("lifecycle annotation");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.text"), 'listed text').toBe("Lifecycle passage");
    // The source link this PR attaches to every listed highlight.
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.id"), 'listed link id').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.name"), 'listed link name').toBe("Lifecycle Source");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.link.url"), 'listed link url').toBe("https://example.com/lifecycle");

    const highlightsGet1Response = await getHighlights(client, headers, {"q": ["annotation"]});
    expect(highlightsGet1Response.statusCode, 'status code').toBe(200);

    // "annotation" appears only in the note, never in the highlighted text.
    expect(getResponseValue(highlightsGet1Response, "response.highlights.0.id"), 'note match id').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGet1Response, "response.highlights.0.comment"), 'note match comment').toBe("lifecycle annotation");
    expect(getResponseValue(highlightsGet1Response, "response.highlights.0.text"), 'note match text').toBe("Lifecycle passage");
    expect(getResponseValue(highlightsGet1Response, "response.highlights.1"), 'only the one note match').toBeNull();
    expect(getResponseValue(highlightsGet1Response, "response.nextCursor"), 'nextCursor').toBeNull();

    const highlightsGet2Response = await getHighlights(client, headers, {"q": ["zzzz-no-such-term"]});
    expect(highlightsGet2Response.statusCode, 'status code').toBe(200);

    // A term in neither the text nor the note returns an empty page, not an unfiltered one.
    expect(getResponseValue(highlightsGet2Response, "response.highlights").length, 'no matches').toBe(0);
    expect(getResponseValue(highlightsGet2Response, "response.highlights.0"), 'no first match').toBeNull();
    expect(getResponseValue(highlightsGet2Response, "response.nextCursor"), 'nextCursor').toBeNull();

    // Request Body
    const highlightsHighlightsPatchRequestBody: string = `{
        "comment": "edited lifecycle annotation"
    }`;

    const highlightsHighlightsPatchResponse = await updateHighlight(
        client,
        headers,
        highlightsHighlightsPatchRequestBody,
        getResponseValue(highlightsPostResponse, "response.id")
    );
    expect(highlightsHighlightsPatchResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.id"), 'patched id').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.comment"), 'patched comment').toBe("edited lifecycle annotation");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.color"), 'colour untouched by a comment-only patch').toBe("green");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.text"), 'text untouched by a comment-only patch').toBe("Lifecycle passage");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.link.id"), 'patched link id').toBe(getResponseValue(linksPostResponse, "response.id"));

    const highlightsGet3Response = await getHighlights(client, headers, {"q": ["edited"]});
    expect(highlightsGet3Response.statusCode, 'status code').toBe(200);

    // The edit is readable on the next list, so it reached the database.
    expect(getResponseValue(highlightsGet3Response, "response.highlights.0.id"), 'edited note match id').toBe(getResponseValue(highlightsPostResponse, "response.id"));
    expect(getResponseValue(highlightsGet3Response, "response.highlights.0.comment"), 'edited note match comment').toBe("edited lifecycle annotation");
    expect(getResponseValue(highlightsGet3Response, "response.highlights.1"), 'only the one edited match').toBeNull();

    const highlightsHighlightsDeleteResponse = await deleteHighlight(
        client,
        headers,
        getResponseValue(highlightsPostResponse, "response.id")
    );
    expect(highlightsHighlightsDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(highlightsHighlightsDeleteResponse, "response"), 'deleted highlight id').toBe(getResponseValue(highlightsPostResponse, "response.id"));

    const collectionsCollectionsDeleteResponse = await deleteCollection(
        client,
        headers,
        getResponseValue(collectionsPostResponse, "response.id")
    );
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
